[CmdletBinding()]param([ValidateSet('Audit','Execute','Rollback')][string]$Mode='Audit',[string]$OutputDirectory=(Join-Path $PSScriptRoot 'Output'),[string]$PlanPath,[string]$PlanSha256,[string]$RollbackPath)
Set-StrictMode -Version Latest;$ErrorActionPreference='Stop';Import-Module (Join-Path $PSScriptRoot 'SystemCleanup.psm1') -Force
switch($Mode){'Audit'{Invoke-KIStackCleanupAudit -OutputDirectory $OutputDirectory|ConvertTo-Json -Depth 20}'Execute'{if(-not$PlanPath-or-not$PlanSha256){throw'Execute requires PlanPath and PlanSha256.'};Invoke-KIStackCleanupExecute -PlanPath $PlanPath -ExpectedPlanSha256 $PlanSha256|ConvertTo-Json -Depth 20}'Rollback'{if(-not$RollbackPath){throw'Rollback requires RollbackPath.'};Restore-KIStackCleanup -RollbackPath $RollbackPath|ConvertTo-Json -Depth 20}}
